param([string]$Root=(Split-Path $PSScriptRoot -Parent))
Import-Module "$Root\Modules\Database.psm1" -Force;Import-Module "$Root\Modules\Core.psm1" -Force;$c=Get-Content "$Root\Config\AppConfig.json" -Raw|ConvertFrom-Json;Initialize-PlatformDatabase (Join-Path $Root $c.DatabasePath) "$Root\Database\Migrations" "$Root\Database\Seed" $c.SeedDatabase
foreach($a in DB 'SELECT * FROM Alerts WHERE Enabled=1'){try{$script:ReportFilters=if($a.FilterJson){$a.FilterJson|ConvertFrom-Json}else{@{Period=$c.DefaultReportPeriod}};$rows=@(&$a.ReportPath);if($a.ContainsFilter){$rows=@($rows|?{($_|Out-String)-match[regex]::Escape($a.ContainsFilter)})};DB 'UPDATE Alerts SET LastRun=@d,LastMatches=@m WHERE Id=@i' @{d=(Get-Date).ToString('s');m=$rows.Count;i=$a.Id}|Out-Null;if($rows.Count){$details=$rows|ConvertTo-Json -Depth 4 -Compress;DB 'INSERT INTO AlertHistory(AlertId,TriggeredOn,Severity,MatchCount,Details) VALUES(@i,@d,@s,@m,@x)' @{i=$a.Id;d=(Get-Date).ToString('s');s=$a.Severity;m=$rows.Count;x=$details}|Out-Null;DB "INSERT INTO NotificationQueue(AlertId,NotificationType,Subject,Payload,Status,CreatedOn) VALUES(@i,'File',@s,@p,'Queued',@d)" @{i=$a.Id;s=$a.Name;p=$details;d=(Get-Date).ToString('s')}|Out-Null}}catch{Add-Audit 'Alert processing' $a.Name Failed $_.Exception.Message}}
